func newPayment() unsafe.Pointer { return unsafe.Pointer(new(customerpayment.Payment)) }

func newNPayment(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]customerpayment.Payment, n)))
}

func ptrPayment(p unsafe.Pointer, c int32) any {
	r := (*customerpayment.Payment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 4:
		return &r.PaymentDate
	case 5:
		return &r.AccountingDate
	case 6:
		return &r.AmountMinor
	case 7:
		return &r.AppliedAmountMinor
	case 8:
		return &r.UnappliedAmountMinor
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return (*string)(unsafe.Pointer(&r.PaymentMethod))
	case 11:
		return &r.ReferenceNumber
	case 12:
		return &r.Memo
	case 13:
		return &r.CurrencyCode
	case 14:
		return &r.ExchangeRate
	case 15:
		return &r.ExchangeRateDate
	case 16:
		return (*string)(unsafe.Pointer(&r.PostedBatchID))
	case 17:
		return (*string)(unsafe.Pointer(&r.ReversalBatchID))
	case 18:
		return (*string)(unsafe.Pointer(&r.ReversedByID))
	case 19:
		return &r.ReversedAt
	case 20:
		return &r.ReversalReason
	case 21:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 22:
		return (*string)(unsafe.Pointer(&r.UpdatedByID))
	case 23:
		return &r.Version
	case 24:
		return &r.CreatedAt
	case 25:
		return &r.UpdatedAt
	}
	return nil
}

func valuePayment(p unsafe.Pointer, c int32) any {
	r := (*customerpayment.Payment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.CustomerID)
	case 4:
		return r.PaymentDate
	case 5:
		return r.AccountingDate
	case 6:
		return r.AmountMinor
	case 7:
		return r.AppliedAmountMinor
	case 8:
		return r.UnappliedAmountMinor
	case 9:
		return string(r.Status)
	case 10:
		return string(r.PaymentMethod)
	case 11:
		if r.ReferenceNumber == "" {
			return nil
		}
		return r.ReferenceNumber
	case 12:
		if r.Memo == "" {
			return nil
		}
		return r.Memo
	case 13:
		return r.CurrencyCode
	case 14:
		return r.ExchangeRate
	case 15:
		if r.ExchangeRateDate == nil {
			return nil
		}
		return *r.ExchangeRateDate
	case 16:
		if r.PostedBatchID == "" {
			return nil
		}
		return string(r.PostedBatchID)
	case 17:
		if r.ReversalBatchID == "" {
			return nil
		}
		return string(r.ReversalBatchID)
	case 18:
		if r.ReversedByID == "" {
			return nil
		}
		return string(r.ReversedByID)
	case 19:
		if r.ReversedAt == nil {
			return nil
		}
		return *r.ReversedAt
	case 20:
		if r.ReversalReason == "" {
			return nil
		}
		return r.ReversalReason
	case 21:
		return string(r.CreatedByID)
	case 22:
		if r.UpdatedByID == "" {
			return nil
		}
		return string(r.UpdatedByID)
	case 23:
		return r.Version
	case 24:
		return r.CreatedAt
	case 25:
		return r.UpdatedAt
	}
	return nil
}

func attachPayment(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*customerpayment.Payment)(p)
	switch rel {
	case 0:
		r.Applications = append(r.Applications, (*customerpayment.Application)(child))
	case 1:
		r.Customer = (*customer.Customer)(child)
	}
}

func beforeCreatePayment(ctx context.Context, p unsafe.Pointer) error {
	return (*customerpayment.Payment)(p).BeforeCreate(ctx)
}

func init() {
	applicationsTable.Relations[0].Target = PaymentsSchema()
	applicationsTable.Relations[1].Target = invoicedb.InvoicesSchema()
	creditMemoApplicationsTable.Relations[0].Target = invoicedb.InvoicesSchema()
	creditMemoApplicationsTable.Relations[1].Target = invoicedb.InvoicesSchema()
	paymentsTable.Relations[0].Target = ApplicationsSchema()
	paymentsTable.Relations[1].Target = customerdb.CustomersSchema()
}

